          "key": "A",
          "text": "1 ms = 1000 s",
          "is_correct": false,
          "explanation": "This reverses the milli- prefix; \\(\\text{milli}=10^{-3}\\), not \\(10^{3}\\)."
        },
        {
          "key": "B",
          "text": "1 ms = 0.001 s",
          "is_correct": true,
          "explanation": "This is correct because the prefix milli means \\(10^{-3}\\). Therefore \\(1\\,\\mathrm{ms}=10^{-3}\\,\\mathrm{s}=0.001\\,\\mathrm{s}\\), and both the number and units are consistent."
        },
        {
          "key": "C",
          "text": "1000 ms = 0.001 s",
          "is_correct": false,
          "explanation": "This mishandles the conversion factor; in fact \\(1000\\,\\mathrm{ms}=1\\,\\mathrm{s}\\)."
        },
        {
          "key": "D",
          "text": "1 = 0.001",
          "is_correct": false,
          "explanation": "This omits units entirely, so it is not a meaningful unit-conversion equation."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
