    {
      "source_id": "9",
      "stem": "If the magnitudes of both charges are doubled and the separation between them is halved, what happens to the magnitude of the electrostatic force each exerts on the other?",
      "options": [
        {
          "key": "A",
          "text": "It stays the same.",
          "is_correct": false,
          "explanation": "This ignores that both the product of the charges and the inverse-square distance factor change."
