    {
      "source_id": "12",
      "stem": "A \\(3.0\\,\\mathrm{kg}\\) cart moving at \\(4.0\\,\\mathrm{m/s}\\) strikes a bumper and rebounds at \\(2.0\\,\\mathrm{m/s}\\) in the opposite direction. The collision lasts \\(0.25\\,\\mathrm{s}\\). What is the magnitude of the average force on the cart during the collision?",
      "options": [
        {
          "key": "A",
          "text": "\\(24\\,\\mathrm{N}\\)",
          "is_correct": false,
          "explanation": "This usually comes from using only one of the speeds instead of the full change in velocity when direction reverses."
